# Step 4: ROT13 over lowercase ASCII letters only
def rot13_lowercase(s):
    result = []
    for c in s:
        if 'a' <= c <= 'z':
            # ROT13 for lowercase
            result.append(chr((ord(c) - ord('a') + 13) % 26 + ord('a')))
        else:
            result.append(c)
    return ''.join(result)

